drop extension if exists "pg_net";


  create table "public"."Friendships" (
    "id" bigint generated by default as identity not null,
    "senderId" uuid not null,
    "receiverId" uuid,
    "created_at" timestamp with time zone not null default now(),
    "status" text
      );


alter table "public"."Friendships" enable row level security;


  create table "public"."ProjectMembers" (
    "id" uuid not null default gen_random_uuid(),
    "userId" uuid not null,
    "projectId" uuid not null
      );


alter table "public"."ProjectMembers" enable row level security;


  create table "public"."Projects" (
    "id" uuid not null default gen_random_uuid(),
    "name" text not null,
    "description" text not null,
    "ownerId" uuid not null
      );


alter table "public"."Projects" enable row level security;


  create table "public"."Tasks" (
    "id" uuid not null default gen_random_uuid(),
    "title" text not null,
    "completed" boolean not null default false,
    "projectId" uuid not null
      );


alter table "public"."Tasks" enable row level security;


  create table "public"."profiles" (
    "id" uuid not null,
    "email" text not null
      );


alter table "public"."profiles" enable row level security;

CREATE UNIQUE INDEX "Friendships_pkey" ON public."Friendships" USING btree (id);

CREATE UNIQUE INDEX "ProjectMembers_pkey" ON public."ProjectMembers" USING btree (id);

CREATE UNIQUE INDEX "Projects_pkey" ON public."Projects" USING btree (id);

CREATE UNIQUE INDEX "Tasks_pkey" ON public."Tasks" USING btree (id);

CREATE UNIQUE INDEX profiles_pkey ON public.profiles USING btree (id);

alter table "public"."Friendships" add constraint "Friendships_pkey" PRIMARY KEY using index "Friendships_pkey";

alter table "public"."ProjectMembers" add constraint "ProjectMembers_pkey" PRIMARY KEY using index "ProjectMembers_pkey";

alter table "public"."Projects" add constraint "Projects_pkey" PRIMARY KEY using index "Projects_pkey";

alter table "public"."Tasks" add constraint "Tasks_pkey" PRIMARY KEY using index "Tasks_pkey";

alter table "public"."profiles" add constraint "profiles_pkey" PRIMARY KEY using index "profiles_pkey";

alter table "public"."Friendships" add constraint "Friendships_receiverId_fkey" FOREIGN KEY ("receiverId") REFERENCES public.profiles(id) ON UPDATE CASCADE not valid;

alter table "public"."Friendships" validate constraint "Friendships_receiverId_fkey";

alter table "public"."Friendships" add constraint "Friendships_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES public.profiles(id) ON UPDATE CASCADE not valid;

alter table "public"."Friendships" validate constraint "Friendships_senderId_fkey";

alter table "public"."ProjectMembers" add constraint "ProjectMembers_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES public."Projects"(id) ON UPDATE CASCADE ON DELETE RESTRICT not valid;

alter table "public"."ProjectMembers" validate constraint "ProjectMembers_projectId_fkey";

alter table "public"."Projects" add constraint "Projects_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES public.profiles(id) not valid;

alter table "public"."Projects" validate constraint "Projects_ownerId_fkey";

alter table "public"."Tasks" add constraint "Tasks_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES public."Projects"(id) ON UPDATE CASCADE ON DELETE RESTRICT not valid;

alter table "public"."Tasks" validate constraint "Tasks_projectId_fkey";

alter table "public"."profiles" add constraint "profiles_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE not valid;

alter table "public"."profiles" validate constraint "profiles_id_fkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into public.profiles (id, email)
  values (new.id, new.email);
  return new;
end;
$function$
;

