  create policy "Allow updates"
  on "public"."Friendships"
  as permissive
  for update
  to public
using ((auth.uid() = "receiverId"))
with check ((auth.uid() = "receiverId"));



  create policy "Enable delete for users based on user_id"
  on "public"."Friendships"
  as permissive
  for delete
  to public
using (((auth.uid() = "senderId") OR (auth.uid() = "receiverId")));



  create policy "Enable insert for users based on senderId"
  on "public"."Friendships"
  as permissive
  for insert
  to public
with check ((( SELECT auth.uid() AS uid) = "senderId"));



  create policy "Enable read access for all users"
  on "public"."Friendships"
  as permissive
  for select
  to public
using (true);



  create policy "Enable insert for authenticated users only"
  on "public"."ProjectMembers"
  as permissive
  for insert
  to authenticated
with check (true);



  create policy "Enable insert for authenticated users only"
  on "public"."Projects"
  as permissive
  for insert
  to authenticated
with check (true);



  create policy "Enable insert for users based on user_id"
  on "public"."Projects"
  as permissive
  for insert
  to public
with check ((( SELECT auth.uid() AS uid) = "ownerId"));



  create policy "Enable read access for all users"
  on "public"."Projects"
  as permissive
  for select
  to public
using (true);



  create policy "Enable insert for authenticated users only"
  on "public"."Tasks"
  as permissive
  for insert
  to authenticated
with check (true);



  create policy "Cualquiera puede leer perfiles"
  on "public"."profiles"
  as permissive
  for select
  to public
using (true);


CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();


